PREFIX ref: <http://brickschema.org/brick/#ref>
SELECT ?name ?point ?series WHERE {
  ?point ref:hasName ?name .
  FILTER(?name IN ("Chiller02","CondPump01","CondPump02"))
  OPTIONAL { ?point ref:hasExternalReference ?series . ?ext a ref:ExternalReference ; ref:hasTimeseriesId ?series . }
}

